"""22.11.2026: родина підтвердила, що фото 1979 р. підписав старший брат Василя Віталійовича — Володимир, син Ніни Гивівни."""
import json
R='/home/claude/rid-shutykh/'; MAN=R+'seed/import/manifest.json'
m=json.load(open(MAN)); have={x.get('key') for x in m}; new=[]
def add(it):
    if it['key'] not in have: new.append(it)
OLD_N='Є припущення, що Володимир — її син (на підставі того, що лист лежав серед її документів, а «братик Вася» і «сестричка Катруся» збігаються з іменами її дітей Василя й Катерини); хто він — уточнити в родини.'
NEW_N='За словами родини (22.11.2026), фото підписав її старший син [[p:volodymyr_n|Володимир]] — старший брат Василя.'
add({'key':'vol-p','kind':'person','id':'volodymyr_n','data':{'n':'Володимир','sex':'m','mo':'nina','fam':['voronky','kruk'],
  'note':'Син [[p:nina|Ніни Гивівни]], старший брат [[p:vasyl_v|Василя]] — за словами родини (22.11.2026). 18 грудня 1979 р. надіслав рідним своє фото у військовій формі з написом: «На довгу незабиваєму память моїм рідним Милій Мамі Татові братіку Васі і бабці сестричці Катрусі в дні моєї служби в місті Москві. Ваш Син Володимир» ([[d:hakvol79|фото й напис]]). Хто його батько, рік народження й прізвище — уточнити в родини.'}})
add({'key':'vol-pp-nina','kind':'personpatch','person':'nina','replace':[[OLD_N,NEW_N]]})
add({'key':'vol-dp','kind':'docpatch','id':'hakvol79','data':{'people':['volodymyr_n','nina'],
  'title':'Фото Володимира у військовій формі з написом рідним, 18.XII.1979',
  'text':'За словами родини (22.11.2026), фото підписав [[p:volodymyr_n|Володимир]] — син [[p:nina|Ніни Гивівни]], старший брат [[p:vasyl_v|Василя]]. «Братик Вася» і «сестричка Катруся» в написі — за нашим деревом Василь (нар. 1972) і Катерина.'}})
h=[x for x in m if x['kind']=='text' and x['id']=='history'][-1]['value']; md=h['md']
a='Є припущення, що Володимир — її син; хто він — уточнюємо в родини.'
assert md.count(a)==1
md=md.replace(a,'За словами родини, це її старший син [[p:volodymyr_n|Володимир]] — старший брат Василя.')
a2='хто такий Володимир з фото 1979 р.; '
if a2 in md: md=md.replace(a2,'рік народження, батько й доля Володимира (фото 1979 р.); ')
add({'key':'text-history-vol2211','kind':'text','id':'history','value':{'md':md,'updated':'2026-11-22'}})
m.extend(new); json.dump(m,open(MAN,'w'),ensure_ascii=False,indent=1); print(len(new))
